import React, { useEffect, useRef, useState } from 'react';
import { Terminal } from 'xterm';
import { FitAddon } from 'xterm-addon-fit';
import 'xterm/css/xterm.css';

function TerminalComponent({ containerId }) {
  const terminalRef = useRef(null);
  const socketRef = useRef(null);
  const terminal = useRef(null);
  const fitAddon = useRef(new FitAddon()).current;
  const [isSocketOpen, setIsSocketOpen] = useState(false); // Track socket state
  let retryCount = 0; // Keep track of reconnection attempts

  // Establish WebSocket connection
  const initializeWebSocket = () => {
    const socket = new WebSocket('ws://localhost:3001');
    socketRef.current = socket;

    socket.onopen = () => {
      console.log('WebSocket connection established');
      setIsSocketOpen(true);
      retryCount = 0; // Reset retry count on successful connection
      socket.send(JSON.stringify({ containerId, cmd: '/bin/sh' }));
    };

    socket.onmessage = (event) => {
      const message = JSON.parse(event.data);
      if (message.output) {
        terminal.current.write(message.output);
      } else if (message.error) {
        terminal.current.write(`\x1B[31m${message.error}\x1B[0m`);
      } else if (message.message) {
        terminal.current.write(message.message);
      }
    };

    socket.onclose = () => {
      console.log('WebSocket connection closed');
      setIsSocketOpen(false);

      // Retry logic with exponential backoff
      if (retryCount < 5) { // Limit to 5 attempts
        retryCount += 1;
        const retryDelay = Math.min(1000 * 2 ** retryCount, 10000); // Exponential backoff, max 10 seconds
        setTimeout(() => {
          console.log(`Reconnecting... Attempt #${retryCount}`);
          initializeWebSocket();
        }, retryDelay);
      } else {
        console.warn('Max WebSocket reconnect attempts reached');
      }
    };

    socket.onerror = (error) => {
      console.error('WebSocket error:', error);
    };
  };

  useEffect(() => {
    if (!terminalRef.current) return;

    terminal.current = new Terminal();
    terminal.current.loadAddon(fitAddon);
    terminal.current.open(terminalRef.current);
    fitAddon.fit();

    initializeWebSocket();

    terminal.current.onData((input) => {
      if (isSocketOpen && socketRef.current.readyState === WebSocket.OPEN) {
        socketRef.current.send(JSON.stringify({ containerId, cmd: input }));
      } else {
        console.warn('WebSocket is not open. Message not sent:', input);
      }
    });

    const handleResize = () => fitAddon.fit();
    window.addEventListener('resize', handleResize);

    return () => {
      if (socketRef.current.readyState === WebSocket.OPEN) {
        socketRef.current.close();
      }
      terminal.current.dispose();
      window.removeEventListener('resize', handleResize);
    };
  }, [containerId, fitAddon, isSocketOpen]);

  return <div ref={terminalRef} style={{ width: '100%', height: '800px' }} />;
}

export default TerminalComponent;
